'use strict';
(() => {
const app=document.getElementById('app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const missing='Chưa có dữ liệu';
const fmt=v=>v==null?missing:typeof v==='boolean'?(v?'Có':'Không'):Array.isArray(v)?(v.length?v.map(item=>typeof item==='object'?Object.values(item).filter(x=>x!=null).join(' · '):String(item)).join('; '):'Không có mục'):typeof v==='object'?Object.values(v).filter(x=>x!=null).join(' · '):String(v);
const state={token:sessionStorage.getItem('forms_token'),actor:null,page:'patients',fields:[],catalog:0,patients:[],patient:null,visit:null,group:null,dirty:{},metadataDirty:{},visitDirty:{},invalid:{},pending:null,viewMessage:'',import:null,busy:false,presets:[]};
const types={integer:'Số nguyên',number:'Số',boolean:'Có / Không',select:'Một lựa chọn',multiselect:'Nhiều lựa chọn',text:'Văn bản',textarea:'Văn bản dài',date:'Ngày',datetime:'Thời điểm',medications:'Danh sách thuốc',results:'Kết quả đã có',unavailable:'Chưa đủ đặc tả'};
const groupsDefault=['Thông tin nền','Triệu chứng và dấu hiệu','Lão khoa và hỗ trợ','Tiền sử và bệnh đồng mắc','Thuốc đang sử dụng','Cận lâm sàng và theo dõi','Chờ đặc tả module','Trường bổ sung'];
const sourceName=s=>({manual:'Nhập tay',excel:'Nhập file Excel',import:'Nhập file',system:'Hệ thống'}[s]||s||missing);
const isAdmin=()=>state.actor?.role==='admin';
const visitFields=()=>state.visit?.fields||[];
const currentValue=code=>Object.hasOwn(state.dirty,code)?state.dirty[code]:state.visit?.values_json?.[code];
const metadata=()=>({...state.visit?.metadata,...state.metadataDirty});
const visitDate=()=>Object.hasOwn(state.visitDirty,'occurred_at')?state.visitDirty.occurred_at:state.visit?.occurred_at;
function displayDate(value){if(!value)return missing;const d=new Date(value);return Number.isNaN(d.getTime())?missing:d.toLocaleString('vi-VN');}
function localDateTime(value){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?'':new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function toISO(value){if(!value)return null;const d=new Date(value);if(Number.isNaN(d.getTime()))throw new Error('Ngày giờ không hợp lệ.');return d.toISOString();}
function ageOn(dob,on=new Date()){if(!dob)return null;const born=String(dob).split('-').map(Number),when=new Date(on);if(born.length!==3||Number.isNaN(when.getTime()))return null;const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(when),part=k=>Number(parts.find(p=>p.type===k)?.value);let age=part('year')-born[0];if(part('month')<born[1]||(part('month')===born[1]&&part('day')<born[2]))age--;return age>=0?age:null;}
function hasDraft(){return Object.keys(state.dirty).length+Object.keys(state.invalid).length+Object.keys(state.metadataDirty).length+Object.keys(state.visitDirty).length>0;}
function resetDraft(){state.dirty={};state.metadataDirty={};state.visitDirty={};state.invalid={};state.pending=null;}
function confirmLeave(message='Có thay đổi chưa lưu. Rời lượt và bỏ phần đang nhập?'){return !hasDraft()||confirm(message);}
async function api(path,{method='GET',body}={}){let response;try{response=await fetch(path,{method,headers:{...(state.token?{Authorization:'Bearer '+state.token}:{}),...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});}catch(e){throw new Error('Không kết nối được máy chủ. Dữ liệu đang nhập được giữ để kiểm tra và thử lại.');}const data=await response.json().catch(()=>({detail:'Máy chủ chưa trả dữ liệu hợp lệ'}));if(!response.ok){const message=response.status===401&&state.token&&path!=='/api/v1/auth/token'?'Phiên đăng nhập không còn hiệu lực. Bản nháp vẫn được giữ trên màn hình.':typeof data.detail==='string'?data.detail:data.detail?.fields?Object.values(data.detail.fields).join('; '):'Yêu cầu chưa được máy chủ chấp nhận.';const e=new Error(message);e.status=response.status;e.detail=data.detail;throw e;}return data;}
let busyControls=null;
function lockBusyUI(){if(!state.busy||!busyControls)return;app.querySelectorAll('button,input,select,textarea').forEach(el=>{if(!busyControls.has(el))busyControls.set(el,el.disabled);el.disabled=true;});app.setAttribute('aria-busy','true');const status=document.getElementById('busy-status');if(status)status.hidden=false;}
async function runAction(work){if(state.busy)return;state.busy=true;busyControls=new Map();lockBusyUI();try{return await work();}finally{state.busy=false;for(const [el,disabled]of busyControls||[])el.disabled=disabled;busyControls=null;app.removeAttribute('aria-busy');const status=document.getElementById('busy-status');if(status)status.hidden=true;}}

function notice(message,kind='error'){const target=document.getElementById('notice');if(target){target.className='status '+kind;target.textContent=message;target.hidden=false;target.focus();}}
function messageBox(){return '<div id="notice" class="status" role="alert" tabindex="-1" hidden></div>';}
function heartMark(extra=''){return `<svg class="heart-mark ${extra}" viewBox="0 0 48 48" fill="none" aria-hidden="true" focusable="false"><path d="M24 41S5 30 5 17a10 10 0 0 1 19-4 10 10 0 0 1 19 4c0 13-19 24-19 24Z" stroke="currentColor" stroke-width="2.8" stroke-linejoin="round"/><path d="M8 24h9l4-8 6 16 4-8h9" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
function shell(content){const role=isAdmin()?'Quản trị viên':'Bác sĩ',name=state.actor.display_name||role;app.innerHTML=`<header><div class="brand">${heartMark()}<span>Hệ thống quản lý bệnh nhân suy tim</span></div><div class="actions"><details class="account"><summary><strong>${esc(name)}</strong>${state.actor.display_name?`<small>${role}</small>`:''}</summary><div class="account-details"><span>Vai trò: ${role}</span><span>Tên đăng nhập: ${esc(state.actor.username)}</span></div></details><button data-action="logout">Đăng xuất</button></div></header><div class="shell"><nav class="sidebar" aria-label="Điều hướng chính"><button data-page="patients" ${state.page==='patients'?'aria-current="page"':''}>Hồ sơ bệnh nhân</button>${!isAdmin()?`<button data-page="excel" ${state.page==='excel'?'aria-current="page"':''}>Nhập file</button>`:`<button data-page="fields" ${state.page==='fields'?'aria-current="page"':''}>Chỉnh biểu mẫu</button>`}</nav><main id="main" tabindex="-1">${messageBox()}<div id="busy-status" class="busy-status" role="status" hidden>Đang tải…</div>${content}</main></div>`;lockBusyUI();}
function portal(){app.innerHTML=`<main id="main" class="login-page"><section class="login-intro" aria-labelledby="product-title"><div class="login-brand">${heartMark('login-mark')}<span>Hồ sơ bệnh nhân · Theo dõi suy tim</span></div><h1 id="product-title" aria-label="Hệ thống quản lý bệnh nhân suy tim">Hệ thống quản lý<br> bệnh nhân suy tim</h1><p class="login-description">Quản lý hồ sơ, thông tin khám và lịch sử theo dõi bệnh nhân suy tim.</p><ul class="login-benefits"><li><span>01</span><div><strong>Thông tin tập trung</strong><p>Tra cứu hồ sơ và dữ liệu từng lượt khám.</p></div></li><li><span>02</span><div><strong>Lịch sử rõ ràng</strong><p>Theo dõi nguồn dữ liệu và các lần chỉnh sửa.</p></div></li><li><span>03</span><div><strong>Thao tác thuận tiện</strong><p>Ghi nhận thông tin theo từng nhóm biểu mẫu.</p></div></li></ul></section><section class="login-panel" aria-labelledby="login-title"><div class="card login-card"><h2 id="login-title">Đăng nhập</h2><p class="muted">Sử dụng tài khoản đã được cấp để tiếp tục.</p>${messageBox()}<form id="login-form"><div class="field"><label for="username">Tên đăng nhập</label><input id="username" name="username" autocomplete="username" required maxlength="80"></div><div class="field"><label for="password">Mật khẩu</label><div class="password-control"><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="200"><button type="button" data-action="toggle-password" aria-controls="password" aria-pressed="false" aria-label="Hiện mật khẩu">Hiện</button></div></div><button class="primary login-submit" type="submit">Đăng nhập</button></form><p class="login-note">Vai trò truy cập được xác định theo tài khoản.</p></div></section></main>`;
document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;try{const token=await api('/api/v1/auth/token',{method:'POST',body:{username:e.target.username.value,password:e.target.password.value}});state.token=token.access_token;sessionStorage.setItem('forms_token',state.token);await initialize();}catch(err){notice(err.message);}finally{button.disabled=false;}};}

async function initialize(){if(!state.token){history.replaceState(null,'','/login');portal();return false;}try{state.actor=await api('/api/v1/auth/me');if(!['admin','doctor'].includes(state.actor.role))throw new Error('Tài khoản chưa có quyền truy cập khu vực này.');await loadFields();await loadPatients();history.replaceState(null,'','/forms');return true;}catch(e){sessionStorage.removeItem('forms_token');state.token=null;state.actor=null;history.replaceState(null,'','/login');portal();notice(e.message);return false;}}
async function loadFields(){const c=await api('/api/forms/fields');state.fields=c.fields;state.catalog=c.revision;}
async function loadPatients(){const patients=await api('/api/forms/patients');state.patients=patients;state.page='patients';showPatients();}
function showPatients(){shell(`<div class="toolbar"><div><h1>Hồ sơ bệnh nhân</h1><p class="muted">${isAdmin()?'Quản lý hồ sơ do bác sĩ tạo.':'Chọn hồ sơ để xem và nhập lượt khám.'}</p></div>${!isAdmin()?'<button class="primary" data-action="new-patient">Tạo hồ sơ</button>':'<button data-page="fields">Chỉnh biểu mẫu</button>'}</div><div class="card"><div class="field"><label for="patient-search">Tìm mã hoặc tên hiển thị</label><input id="patient-search" type="search" placeholder="Nhập mã BN hoặc tên"></div><div id="patient-list" class="row-list">${patientItems(state.patients)}</div></div>`);document.getElementById('patient-search').oninput=e=>{const q=e.target.value.trim().toLowerCase();document.getElementById('patient-list').innerHTML=patientItems(state.patients.filter(p=>(p.code+' '+(p.display_name||'')).toLowerCase().includes(q)),Boolean(q));};}
function patientItems(list,filtered=false){return list.length?list.map(p=>{const age=ageOn(p.date_of_birth),sex={male:'Nam',female:'Nữ',other:'Khác'}[p.sex],demographics=[age===null?null:age+' tuổi',sex].filter(Boolean).join(' · ');return `<div class="list-item"><div><strong>${esc(p.display_name||missing)}</strong><p class="patient-code">${esc(p.code)}${demographics?' · '+esc(demographics):''}</p><p class="visit-time">${p.latest_visit_at?'Lần khám gần nhất: '+esc(displayDate(p.latest_visit_at))+(p.latest_visit_external_id?' · '+esc(p.latest_visit_external_id):''):'Chưa có thời điểm khám gần nhất'}</p></div><button data-patient="${esc(p.id)}">Mở hồ sơ</button></div>`;}).join(''):filtered?'<div class="empty">Không tìm thấy hồ sơ phù hợp. <button data-action="clear-search">Xóa tìm kiếm</button></div>':'<div class="empty">Chưa có hồ sơ trong phạm vi tài khoản.</div>';}

function demographicContent(p,at){const age=at===null?null:ageOn(p.date_of_birth,at||new Date());return `<dl class="facts"><div><dt>Ngày sinh</dt><dd>${esc(p.date_of_birth?new Date(p.date_of_birth+'T00:00:00').toLocaleDateString('vi-VN'):missing)}</dd></div><div><dt>Tuổi ${at!==undefined?'tại ngày khám':'hiện tại'}</dt><dd>${age===null?missing:age}</dd></div><div><dt>Giới tính</dt><dd>${esc({male:'Nam',female:'Nữ',other:'Khác'}[p.sex]||missing)}</dd></div><div><dt>Mã BHYT</dt><dd>${esc(p.insurance_number||missing)}</dd></div><div><dt>Mã nguồn bệnh viện</dt><dd>${esc(p.external_id||missing)}</dd></div></dl>`;}
function diagnosisContent(m={}){return `<dl class="facts"><div><dt>Mã bệnh chính ICD-10</dt><dd>${esc(m.primary_diagnosis_code||missing)}</dd></div><div><dt>Mã bệnh kèm theo ICD-10</dt><dd>${esc(fmt(m.secondary_diagnosis_codes))}</dd></div></dl>`;}
function visitCode(v){return v.external_id||('Lượt '+v.id.slice(0,8));}
function context(){if(!state.patient)return '';const v=state.visit,m=metadata(),p=v?.demographics_snapshot||state.patient,age=v&&visitDate()?ageOn(p.date_of_birth,visitDate()):null;return `<section class="context encounter-context" aria-label="Thông tin lượt đang mở"><div class="context-identity"><strong>${esc(p.display_name||state.patient.display_name||missing)}</strong><span>${esc(state.patient.code)}<span id="context-age">${age===null?'':' · '+age+' tuổi tại lần khám'}</span>${isAdmin()?' · Chỉ đọc':''}</span></div>${v?`<p class="context-visit"><strong>${esc(visitCode(v))}</strong><span id="context-occurred">Thời điểm khám: ${esc(displayDate(visitDate()))}</span></p><details><summary>Thông tin hành chính và chi tiết lượt khám</summary>${demographicContent(p,visitDate())}${diagnosisContent(m)}<dl class="facts"><div><dt>Bác sĩ khám</dt><dd>${esc(m.examining_doctor||missing)}</dd></div><div><dt>Khoa/phòng</dt><dd>${esc(m.department||missing)}</dd></div><div><dt>Tiếp nhận</dt><dd>${esc(displayDate(m.admitted_at))}</dd></div><div><dt>Kết thúc</dt><dd>${esc(displayDate(m.ended_at))}</dd></div></dl><p class="muted">Phiên bản biểu mẫu: v${esc(v.catalog_revision)}</p></details>`:''}</section>`;}

const repeatLabels={test_code:'Loại xét nghiệm',name:'Tên',ingredient:'Hoạt chất',dose:'Liều ghi nhận ban đầu',strength:'Hàm lượng ghi nhận',dose_value:'Liều mỗi lần',dose_unit:'Đơn vị liều',route:'Đường dùng',frequency:'Tần suất ghi nhận',start_date:'Ngày bắt đầu',end_date:'Ngày kết thúc',status:'Trạng thái thuốc',category:'Nhóm thuốc/sản phẩm',source:'Nguồn kết quả/thông tin',observed_at:'Thời điểm thực hiện/ghi nhận theo nguồn',value:'Giá trị',unit:'Đơn vị'};
const repeatOptions={status:[{code:'current',label:'Đang sử dụng'},{code:'planned',label:'Dự kiến'},{code:'stopped',label:'Đã ngừng'}],category:[{code:'prescription',label:'Thuốc kê đơn'},{code:'otc',label:'Thuốc không kê đơn (OTC)'},{code:'supplement',label:'Thực phẩm bổ sung/TPCN'},{code:'traditional',label:'Y học cổ truyền'}]};
function repeatColumns(f){return f.type==='medications'?['name','ingredient','dose',...(f.contract_version>=2?['strength','dose_value','dose_unit']:[]),'route','frequency','observed_at',...(f.contract_version>=2?['start_date','end_date','status','category','source']:[])]:[...(f.contract_version>=2?['test_code']:[]),'name','value','unit','observed_at',...(f.contract_version>=2?['source']:[])];}
function repeatChoices(f,column,row){if(column==='test_code')return f.result_tests||[];if(column==='unit'&&f.contract_version>=2){const units=f.result_tests?.find(t=>t.code===row.test_code)?.units||[];return units.length?units.map(unit=>({code:unit,label:unit})):null;}return repeatOptions[column]||null;}
function repeatOptionsHTML(choices,value){return `<option value="">${missing}</option>${value!=null&&!choices.some(c=>String(c.code)===String(value))?`<option value="${esc(value)}" selected>Giá trị đã ghi: ${esc(value)}</option>`:''}${choices.map(c=>`<option value="${esc(c.code)}" ${value!=null&&String(value)===String(c.code)?'selected':''}>${esc(c.label)}</option>`).join('')}`;}
function repeatControl(f,row,index,column,disabled=''){const id=`f-${f.code}-${index}-${column}`,key=f.code+':'+index+':'+column,error=state.invalid[key]||'',choices=repeatChoices(f,column,row),type=['value','dose_value'].includes(column)?'number':column==='observed_at'?'datetime-local':['start_date','end_date'].includes(column)?'date':'text',attrs=`id="${esc(id)}" data-repeat="${esc(f.code)}" data-index="${index}" data-column="${column}" aria-describedby="error-${esc(id)}" aria-invalid="${error?'true':'false'}"${disabled}`,value=column==='observed_at'?localDateTime(row[column]):row[column],label=column==='name'&&f.type==='results'&&f.contract_version>=2?'Tên chỉ số/kết quả gốc':repeatLabels[column];return `<div class="field"><label for="${esc(id)}">${esc(label)}</label>${choices?`<select ${attrs}>${repeatOptionsHTML(choices,row[column])}</select>`:`<input ${attrs} type="${type}" ${type==='number'?'step="any"':type==='datetime-local'?'step="60"':''} ${column==='dose_value'?'min="0"':''} value="${esc(value)}" maxlength="5000">`}${column==='unit'&&choices?'<small>Chọn đơn vị đã xác nhận cho xét nghiệm này.</small>':''}${column==='unit'&&!choices&&f.contract_version>=2?'<small>Ghi đúng đơn vị của kết quả nguồn; chưa có danh mục đơn vị xác nhận.</small>':''}<div id="error-${esc(id)}" class="field-error" role="status">${esc(error)}</div></div>`;}
function repeatValueLabel(f,column,value,row){if(value==null)return missing;if(column==='observed_at')return displayDate(value);if(column==='start_date'||column==='end_date')return value;return repeatChoices(f,column,row)?.find(c=>String(c.code)===String(value))?.label||fmt(value);}
function valueContent(f,value){if(value==null)return missing;if(f?.type==='boolean')return value?'Có':'Không';if(['select','multiselect'].includes(f?.type)){const label=v=>f.choices?.find(c=>String(c.code)===String(v))?.label||v;return esc(Array.isArray(value)?(value.length?value.map(label).join(', '):'Không có mục'):label(value));}if(['medications','results'].includes(f?.type)){return value.length?`<div class="repeat-items">${value.map((r,i)=>`<div class="repeat-card"><strong>${i+1}. ${esc(r.name||f.result_tests?.find(t=>t.code===r.test_code)?.label||missing)}</strong><dl class="facts">${Object.entries(r).filter(([k])=>k!=='name').map(([k,v])=>`<div><dt>${esc(repeatLabels[k]||k)}</dt><dd>${esc(repeatValueLabel(f,k,v,r))}</dd></div>`).join('')}</dl></div>`).join('')}</div>`:'Không có mục';}return esc(f?.type==='datetime'?displayDate(value):fmt(value))+(f?.unit&&value!==null?' '+esc(f.unit):'');}
function latestSummary(v,summaries={}){const pick=k=>Object.hasOwn(summaries,k)?summaries[k]:v,disease=pick('disease'),med=pick('medications'),allergy=pick('allergy'),m=disease?.metadata||{},a=allergy?.metadata||{};const provenance=source=>source?`<p class="provenance">Theo ${esc(visitCode(source))} — ${esc(displayDate(source.occurred_at))}</p>`:'';const meds=med?(med.fields||[]).filter(f=>f.type==='medications'&&med.values_json?.[f.code]!=null):[];return `<div class="summary-sections"><section class="summary-section"><h3>Thông tin gần nhất</h3>${provenance(disease)}${disease?diagnosisContent(m)+(m.reason?'<p><strong>Lý do khám:</strong> '+esc(m.reason)+'</p>':'')+(m.hpi?'<p><strong>Bệnh sử/diễn biến:</strong> '+esc(m.hpi)+'</p>':''):'<p class="muted">Chưa có thông tin bệnh đã ghi nhận.</p>'}</section><section class="summary-section"><h3>Thuốc ghi nhận</h3>${provenance(med)}${meds.length?meds.map(f=>valueContent(f,med.values_json[f.code])).join(''):'<p class="muted">Chưa có dữ liệu thuốc.</p>'}<p class="muted">Cần đối chiếu lại thuốc khi tái khám.</p></section><section class="summary-section"><h3>Dị ứng/phản ứng có hại</h3>${provenance(allergy)}<p>${esc({unknown:'Chưa hỏi/chưa biết',none:'Đã xác nhận không có',known:a.allergy_details||'Đã ghi nhận, chưa có mô tả'}[a.allergy_status]||missing)}</p></section></div>`;}

async function openPatient(id){const data=await api('/api/forms/patients/'+id+'/overview');captureMapping();state.patient=data.patient;state.visit=null;resetDraft();state.page='patients';const visits=[...(data.visits||[])].sort((a,b)=>(b.occurred_at?new Date(b.occurred_at).getTime():-Infinity)-(a.occurred_at?new Date(a.occurred_at).getTime():-Infinity));shell(`<div class="toolbar"><div><h1>${esc(data.patient.code)} · ${esc(data.patient.display_name||missing)}</h1><button data-page="patients">← Hồ sơ bệnh nhân</button></div><div class="actions"><button data-action="edit-patient">Chỉnh hành chính</button><button data-action="patient-history">Lịch sử hành chính</button>${isAdmin()?'<button data-page="fields">Chỉnh biểu mẫu</button>':'<button class="primary" data-action="new-visit">Mở lượt mới</button>'}</div></div><section class="card"><h2>Thông tin hành chính</h2>${demographicContent(data.patient)}<small>Ngày tạo: ${esc(displayDate(data.patient.created_at))} · Cập nhật: ${esc(displayDate(data.patient.updated_at))}</small></section><section class="card"><h2>Thông tin bệnh và thuốc</h2>${latestSummary(data.latest_visit,data.summary_visits)}</section><section class="card"><h2>Các lượt khám</h2><div class="row-list">${visits.length?visits.map(v=>`<div class="list-item"><div><strong>${esc(visitCode(v))}</strong><p class="visit-time">${esc({new:'Khám mới · ',followup:'Tái khám · '}[v.metadata?.visit_type]||'')}${esc(v.occurred_at?displayDate(v.occurred_at):'Chưa có thời điểm khám')}</p></div><button data-visit="${esc(v.id)}">Mở lượt khám</button></div>`).join(''):'<div class="empty">Chưa có lượt khám.</div>'}</div></section>`);}
async function openVisit(id){const visit=await api('/api/forms/visits/'+id);if(!Array.isArray(visit.fields))throw new Error('Chưa đọc được cấu trúc đã lưu của lượt khám. Vui lòng tải lại.');let patient=state.patients.find(p=>p.id===visit.patient_id)||(state.patient?.id===visit.patient_id?state.patient:null);if(!patient)patient=(await api('/api/forms/patients/'+visit.patient_id+'/overview')).patient;if(!patient||patient.id!==visit.patient_id)throw new Error('Chưa đối chiếu được hồ sơ của lượt. Bản nháp hiện tại được giữ.');captureMapping();state.visit=visit;state.patient=patient;resetDraft();state.group=null;state.viewMessage='Đã tải dữ liệu';showForm();}
function fieldWidget(f,value,preview=false){const id='f-'+f.code,code=esc(f.code),readOnly=preview||isAdmin(),disabled=readOnly?' disabled':'',error=Object.entries(state.invalid).filter(([key])=>key.split(':')[0]===f.code).map(([,message])=>message).join(' '),constraints=f.constraints||{};const labelTag=['medications','results'].includes(f.type)||readOnly&&!preview?'span':'label',start=`<div class="field ${['medications','results'].includes(f.type)?'repeat':''}"><${labelTag} ${labelTag==='label'?'for="'+id+'"':'class="label"'}>${esc(f.label)}${f.unit?' <span class="unit">'+esc(f.unit)+'</span>':''}</${labelTag}>`;let control='';
if(f.type==='unavailable'||!f.active)return `<div class="unavailable"><strong>${esc(f.label)}</strong><p>${!f.active?'Trường đã ngừng dùng. Giá trị đã lưu: '+esc(fmt(value)):'Chưa khả dụng — '+({ai_output:'đầu ra AI chưa triển khai.',derived:'giá trị tính chưa đủ quy tắc.',calculated:'giá trị tính chưa đủ quy tắc.',module_linked:'dữ liệu liên kết module chưa có hợp đồng đầu vào.',recorded_input:'đầu vào ghi nhận chưa đủ đặc tả để nhập.',measured_input:'đầu vào đo/thu thập chưa đủ đặc tả để nhập.'}[f.data_role||f.value_role]||'chưa đủ đặc tả để nhập.')}</p><small>${esc(f.help||'Chưa có nguồn xác nhận cấu trúc.')}</small></div>`;
if(!preview&&state.visit?.demographics_snapshot){const snapshot=state.visit.demographics_snapshot;let derivedLabel,derivedValue,explanation;if(f.code==='tuoi'&&snapshot.date_of_birth){derivedLabel='Tuổi tại ngày khám';derivedValue=visitDate()?ageOn(snapshot.date_of_birth,visitDate()):null;explanation='Tính từ ngày sinh đã ghi ở lượt này; không tạo thêm giá trị nhập tay.';}if(f.code==='gioi_tinh'&&snapshot.sex){derivedLabel='Giới tính theo hành chính của lượt';derivedValue={male:'Nam',female:'Nữ',other:'Khác'}[snapshot.sex]||missing;explanation='Theo thông tin hành chính đã gắn với lượt khám.';}if(derivedLabel)return `<div class="field"><span class="label">${derivedLabel}</span><div class="readonly-value" id="derived-${code}">${esc(fmt(derivedValue))}${f.code==='tuoi'&&derivedValue!==null?' tuổi':''}</div><small>${explanation}</small>${value!=null?`<details><summary>Giá trị từng ghi riêng trong biểu mẫu</summary><p>${valueContent(f,value)}</p></details>`:''}</div>`;}
if(readOnly&&!preview)return start+`<div class="readonly-value">${valueContent(f,value)}</div></div>`;
if(f.type==='boolean'||f.type==='select'){const choices=f.type==='boolean'?[{code:'true',label:'Có'},{code:'false',label:'Không'}]:(f.choices||[]);control=`<select id="${id}" data-field="${code}" aria-describedby="help-${code} error-${code}" aria-invalid="${error?'true':'false'}"${disabled}><option value="">${missing}</option>${choices.map(c=>`<option value="${esc(c.code)}" ${value!=null&&String(value)===String(c.code)?'selected':''}>${esc(c.label)}</option>`).join('')}</select>`;}
else if(f.type==='multiselect'){control=`<label class="check"><input type="checkbox" data-multi-known="${code}" ${value!=null?'checked':''}${disabled}> Đã xác định danh sách (có thể không có mục)</label><select multiple id="${id}" data-field="${code}" aria-describedby="help-${code} error-${code}" aria-invalid="${error?'true':'false'}" ${value==null?'disabled':disabled} aria-label="${esc(f.label)}">${(f.choices||[]).map(c=>`<option value="${esc(c.code)}" ${Array.isArray(value)&&value.includes(c.code)?'selected':''}>${esc(c.label)}</option>`).join('')}</select>`;}
else if(f.type==='textarea')control=`<textarea id="${id}" data-field="${code}" aria-describedby="help-${code} error-${code}" aria-invalid="${error?'true':'false'}" maxlength="5000"${disabled}>${esc(value)}</textarea>`;
else if(['medications','results'].includes(f.type)){const columns=repeatColumns(f);control=`<p class="muted">${value==null?missing:value.length+' mục đã ghi nhận'}</p>${f.contract_version>=2&&f.type==='results'?'<p class="unit-note">Chỉ ghi kết quả đã có. Giữ tên chỉ số, đơn vị, thời điểm thực hiện và nguồn theo tài liệu gốc.</p>':''}<div class="repeat-items">${(value||[]).map((row,i)=>`<fieldset class="repeat-card"><legend>Mục ${i+1}</legend>${columns.map(c=>repeatControl(f,row,i,c,disabled)).join('')}<button type="button" data-remove-item="${code}" data-index="${i}"${disabled}>Xóa mục ${i+1}</button></fieldset>`).join('')}</div><div class="actions"><button type="button" data-add-item="${code}"${disabled}>Thêm mục</button><button type="button" data-empty-list="${code}"${disabled}>Xác nhận danh sách rỗng</button><button type="button" data-null-list="${code}"${disabled}>Chưa có dữ liệu</button></div>`;}
else control=`<input id="${id}" data-field="${code}" aria-describedby="help-${code} error-${code}" aria-invalid="${error?'true':'false'}" type="${['integer','number'].includes(f.type)?'number':f.type==='date'?'date':f.type==='datetime'?'datetime-local':'text'}" ${f.type==='integer'?'step="1"':f.type==='number'?'step="any"':''} ${constraints.minimum!==undefined?'min="'+constraints.minimum+'"':''} ${constraints.maximum!==undefined?'max="'+constraints.maximum+'"':''} value="${esc(f.type==='datetime'?localDateTime(value):value)}" maxlength="5000"${disabled}>`;
return start+control+`<small id="help-${code}">${esc(f.help||'')}</small><div id="error-${code}" class="field-error" role="status">${esc(error)}</div></div>`;}
function metadataFields(readonly=false){const m=metadata(),dis=readonly?' disabled':'',field=(key,label,type='text')=>`<div class="field"><label for="meta-${key}">${label}</label>${type==='textarea'?`<textarea id="meta-${key}" data-metadata="${key}" aria-describedby="error-meta-${key}" aria-invalid="${state.invalid['meta-'+key]?'true':'false'}"${dis}>${esc(m[key])}</textarea>`:`<input id="meta-${key}" data-metadata="${key}" aria-describedby="error-meta-${key}" aria-invalid="${state.invalid['meta-'+key]?'true':'false'}" type="${type}" value="${esc(type==='datetime-local'?localDateTime(m[key]):Array.isArray(m[key])?m[key].join(', '):m[key])}"${dis}>`}<div id="error-meta-${key}" class="field-error" role="status">${esc(state.invalid['meta-'+key]||'')}</div></div>`;return `<fieldset class="visit-details"><legend>Thông tin lượt khám</legend><div class="field"><label for="visit-occurred">Thời điểm khám</label><input id="visit-occurred" aria-describedby="error-occurred_at" aria-invalid="${state.invalid.occurred_at?'true':'false'}" data-visit-field="occurred_at" type="datetime-local" value="${esc(localDateTime(visitDate()))}"${dis}><small>Ngày khám gốc; có thể nhập bù.</small><div id="error-occurred_at" class="field-error" role="status">${esc(state.invalid.occurred_at||'')}</div></div><div class="field"><label for="meta-visit_type">Loại khám</label><select id="meta-visit_type" data-metadata="visit_type"${dis}><option value="">${missing}</option><option value="new" ${m.visit_type==='new'?'selected':''}>Khám mới</option><option value="followup" ${m.visit_type==='followup'?'selected':''}>Tái khám</option></select></div>${field('reason','Lý do khám')}${field('hpi','Bệnh sử/diễn biến ngắn','textarea')}${field('primary_diagnosis_code','Mã bệnh chính ICD-10')}${field('secondary_diagnosis_codes','Mã bệnh kèm theo ICD-10 (phân tách bằng dấu phẩy)')}${field('examining_doctor','Bác sĩ khám')}${field('department','Khoa/phòng')}${field('admitted_at','Thời điểm tiếp nhận','datetime-local')}${field('ended_at','Thời điểm kết thúc','datetime-local')}<div class="field"><label for="meta-allergy_status">Dị ứng/phản ứng có hại</label><select id="meta-allergy_status" data-metadata="allergy_status"${dis}><option value="">${missing}</option>${[['unknown','Chưa hỏi/chưa biết'],['none','Đã xác nhận không có'],['known','Đã ghi nhận']].map(([v,l])=>`<option value="${v}" ${m.allergy_status===v?'selected':''}>${l}</option>`).join('')}</select></div>${field('allergy_details','Mô tả dị ứng/phản ứng có hại','textarea')}</fieldset>`;}
function groupDirtyCount(group){const codes=visitFields().filter(f=>f.group===group).map(f=>f.code),clinical=new Set([...Object.keys(state.dirty),...Object.keys(state.invalid)].map(c=>c.split(':')[0]).filter(c=>codes.includes(c))).size;const visitKeys=new Set([...Object.keys(state.metadataDirty).map(k=>'meta-'+k),...Object.keys(state.visitDirty),...Object.keys(state.invalid).filter(k=>k==='occurred_at'||k.startsWith('meta-'))]);return clinical+(group==='Thông tin nền'?visitKeys.size:0);}
function groupStatus(group){const n=groupDirtyCount(group),fields=visitFields().filter(f=>f.group===group),available=fields.some(f=>f.active&&f.type!=='unavailable')||group==='Thông tin nền';return n?n+' thay đổi chưa lưu':!available?'Chưa hỗ trợ nhập':state.viewMessage==='Đã lưu'?'Đã lưu':'Đã tải';}
function groupContent(fields){const available=fields.filter(f=>f.active&&f.type!=='unavailable'),unavailable=fields.filter(f=>!f.active||f.type==='unavailable');return `<div class="clinical-grid">${available.map(f=>fieldWidget(f,currentValue(f.code))).join('')}</div>${unavailable.length?`<details class="unavailable-section"><summary>${available.length?'Các mục chưa hỗ trợ nhập':'Trạng thái các mục chưa hỗ trợ'} (${unavailable.length})</summary><p class="muted">Các mục này chưa hỗ trợ nhập liệu. Thông tin dưới đây dùng để đối chiếu phạm vi và nguồn.</p><div class="unavailable-items">${unavailable.map(f=>fieldWidget(f,currentValue(f.code))).join('')}</div></details>`:''}`;}
function showForm(){state.page='patients';const fields=visitFields(),groups=[...new Set(fields.map(f=>f.group))];if(!groups.includes('Thông tin nền'))groups.unshift('Thông tin nền');state.group=groups.includes(state.group)?state.group:groups[0];shell(`<div class="toolbar"><div><h1>Lượt khám</h1><button data-action="back-visits">← Hồ sơ bệnh nhân</button></div><div class="actions"><button data-action="history">Lịch sử chỉnh sửa</button><button data-action="reload-visit">Tải lại</button></div></div>${context()}<div class="form-layout"><nav class="groups" aria-label="Nhóm biểu mẫu"><div class="compact-groups field"><label for="group-select">Nhóm biểu mẫu</label><select id="group-select" data-group-select>${groups.map(g=>`<option value="${esc(g)}" ${g===state.group?'selected':''}>${esc(g)} · ${esc(groupStatus(g))}</option>`).join('')}</select></div><div class="group-buttons">${groups.map(g=>`<button data-group="${esc(g)}" ${g===state.group?'aria-current="true" class="active"':''}>${esc(g)}<small data-group-count="${esc(g)}">${esc(groupStatus(g))}</small></button>`).join('')}</div></nav><section class="card clinical"><h2 tabindex="-1">${esc(state.group)}</h2>${state.group==='Thông tin nền'?metadataFields(isAdmin()):''}${groupContent(fields.filter(f=>f.group===state.group))}<details class="technical-details"><summary>Chi tiết biểu mẫu</summary><p>Phiên bản v${esc(state.visit.catalog_revision)}. “Đã tải” chỉ cho biết dữ liệu đã được đọc, chưa xác nhận điền đủ thông tin.</p></details></section></div>${!isAdmin()?`<div class="savebar"><div><strong id="save-status" role="status">${hasDraft()?'Có thay đổi chưa lưu':esc(state.viewMessage||'Chưa có thay đổi')}</strong><small>Lưu thông tin đã nhập cho lượt khám này.</small></div><button class="primary" data-action="save">Lưu thay đổi</button></div>`:''}`);}

function refreshDraftStatus(){const status=document.getElementById('save-status');if(status)status.textContent=hasDraft()?'Có thay đổi chưa lưu'+(Object.keys(state.invalid).length?' · Có lỗi cần sửa':''):(state.viewMessage||'Chưa có thay đổi');app.querySelectorAll('[data-group-count]').forEach(el=>{const n=groupDirtyCount(el.dataset.groupCount);el.textContent=n?n+' thay đổi chưa lưu':groupStatus(el.dataset.groupCount);});const compact=document.getElementById('group-select');if(compact)for(const option of compact.options||[])option.textContent=option.value+' · '+groupStatus(option.value);}
function dirty(code,value){if(JSON.stringify(value)===JSON.stringify(state.visit.values_json?.[code]??null))delete state.dirty[code];else state.dirty[code]=value;state.pending=null;refreshDraftStatus();}
function setInvalid(key,message){if(message)state.invalid[key]=message;else delete state.invalid[key];const [code,index,column]=key.split(':'),el=document.getElementById('error-'+code),control=document.getElementById('f-'+code)||(code.startsWith('meta-')?document.getElementById(code):code==='occurred_at'?document.getElementById('visit-occurred'):null);if(control)control.setAttribute('aria-invalid',Object.keys(state.invalid).some(k=>k.split(':')[0]===code)?'true':'false');if(el)el.textContent=Object.entries(state.invalid).filter(([k])=>k.split(':')[0]===code).map(([,v])=>v).join(' ');if(index!==undefined&&column){const id=`f-${code}-${index}-${column}`,input=document.getElementById(id),inline=document.getElementById('error-'+id);if(input)input.setAttribute('aria-invalid',message?'true':'false');if(inline)inline.textContent=message||'';}refreshDraftStatus();}
function numericValue(el,field){if(el.validity?.badInput||el.value!==''&&!Number.isFinite(Number(el.value)))throw new Error('Cần nhập số hợp lệ. Giá trị lỗi không được lưu thành ô trống.');if(el.value==='')return null;const n=Number(el.value),c=field.constraints||{};if(field.type==='integer'&&!Number.isInteger(n))throw new Error('Cần số nguyên.');if(c.minimum!==undefined&&n<c.minimum)throw new Error('Giá trị phải từ '+c.minimum+(field.unit?' '+field.unit:'')+' trở lên.');if(c.maximum!==undefined&&n>c.maximum)throw new Error('Giá trị không được vượt '+c.maximum+(field.unit?' '+field.unit:'')+'.');return n;}
async function save(){if(isAdmin())throw new Error('Admin chỉ đọc dữ liệu khám.');if(Object.keys(state.invalid).length){notice('Sửa giá trị không hợp lệ trước khi lưu.');return;}if(!hasDraft()){notice('Chưa có thay đổi cần lưu.','success');return;}const status=document.getElementById('save-status');if(status)status.textContent='Đang lưu…';state.pending=state.pending||{expected_revision:state.visit.revision,catalog_revision:state.visit.catalog_revision,mutation_id:crypto.randomUUID(),values:structuredClone(state.dirty),...(Object.keys(state.metadataDirty).length?{metadata:structuredClone(state.metadataDirty)}:{}),...state.visitDirty};try{const sent=state.pending,result=await api('/api/forms/visits/'+state.visit.id,{method:'PATCH',body:sent});state.visit.values_json={...state.visit.values_json,...sent.values};state.visit.metadata={...state.visit.metadata,...sent.metadata};if(Object.hasOwn(sent,'occurred_at'))state.visit.occurred_at=sent.occurred_at;state.visit.revision=result.revision;resetDraft();state.viewMessage='Đã lưu';try{state.visit=await api('/api/forms/visits/'+state.visit.id);showForm();notice('Đã lưu dữ liệu.','success');}catch(e){showForm();notice('Đã lưu nhưng chưa tải lại được. '+e.message,'warn');}}catch(e){const status=document.getElementById('save-status');if(status)status.textContent='Lưu không thành công — bản nháp được giữ';notice(e.status===409?e.message+' Bản nháp vẫn được giữ để đối chiếu.':e.message);if(e.detail?.fields)for(const [code,msg]of Object.entries(e.detail.fields))setInvalid(code,msg);}}
function modal(title,content,onSubmit,submitLabel='Lưu'){document.querySelector('dialog')?.remove();const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','dialog-title');dialog.innerHTML=`<form><div class="toolbar"><h2 id="dialog-title">${esc(title)}</h2><button type="button" data-close aria-label="Đóng">×</button></div><div class="dialog-error" role="alert" tabindex="-1"></div>${content}<div class="actions dialog-actions"><button type="button" data-close>Hủy</button><button class="primary" type="submit">${submitLabel}</button></div></form>`;document.body.append(dialog);let submitting=false;dialog.addEventListener('cancel',e=>{if(submitting)e.preventDefault();});dialog.addEventListener('close',()=>dialog.remove());dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{if(!submitting)dialog.close();});dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(submitting)return;const data=new FormData(e.target),controls=[...dialog.querySelectorAll('button,input,select,textarea')].map(el=>[el,el.disabled]);submitting=true;dialog.setAttribute('aria-busy','true');controls.forEach(([el])=>el.disabled=true);try{await onSubmit(data,dialog);}catch(err){const el=dialog.querySelector('.dialog-error');el.className='dialog-error status error';el.textContent=err.message;el.focus();}finally{submitting=false;dialog.removeAttribute('aria-busy');controls.forEach(([el,disabled])=>el.disabled=disabled);}};dialog.showModal();dialog.querySelector('input:not([disabled]),select:not([disabled]),textarea:not([disabled])')?.focus();return dialog;}
function patientInputs(p={}){return `<p class="muted">Mã BN do hệ thống cấp. Thông tin chưa biết có thể để trống.</p><div class="field"><label for="patient-name">Tên giả lập</label><input id="patient-name" name="display_name" ${p.id?'required':''} value="${esc(p.display_name)}" placeholder="Hệ thống tự tạo: Người bệnh giả lập xxxxx" pattern="Người bệnh giả lập [0-9]+" maxlength="200"><small>Giữ tên giả lập trong dữ liệu trình diễn.</small></div><div class="field"><label for="patient-dob">Ngày sinh</label><input id="patient-dob" name="date_of_birth" type="date" value="${esc(p.date_of_birth)}"><small id="patient-age">Tuổi hiện tại: ${ageOn(p.date_of_birth)??missing}</small></div><div class="field"><label for="patient-sex">Giới tính</label><select id="patient-sex" name="sex"><option value="">${missing}</option>${[['male','Nam'],['female','Nữ'],['other','Khác']].map(([v,l])=>`<option value="${v}" ${v===p.sex?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="patient-insurance">Mã BHYT</label><input id="patient-insurance" name="insurance_number" value="${esc(p.insurance_number)}" maxlength="100"></div><div class="field"><label for="external-id">Mã nguồn bệnh viện (nếu có)</label><input id="external-id" name="external_id" value="${esc(p.external_id)}" maxlength="100"></div>`;}
function bindPatientAge(){document.getElementById('patient-dob').oninput=e=>{document.getElementById('patient-age').textContent='Tuổi hiện tại: '+(ageOn(e.target.value)??missing);};}
function patientBody(data){return Object.fromEntries(['display_name','date_of_birth','sex','insurance_number','external_id'].map(k=>[k,data.get(k)||null]));}
function newPatient(){if(isAdmin())return;const id=crypto.randomUUID();modal('Tạo hồ sơ',patientInputs(),async(data,d)=>{const body=patientBody(data);if(!body.display_name)delete body.display_name;const p=await api('/api/forms/patients',{method:'POST',body:{id,...body}});state.patients.push(p);d.close();await openPatient(p.id);notice('Đã tạo hồ sơ. Có thể mở lượt khám đầu tiên.','success');});bindPatientAge();}
function editPatient(){const p=state.patient,mutation_id=crypto.randomUUID();modal('Chỉnh thông tin hành chính',patientInputs(p),async(data,d)=>{await api('/api/forms/patients/'+p.id,{method:'PATCH',body:{expected_revision:p.demographic_revision,mutation_id,...patientBody(data)}});d.close();await loadPatients();await openPatient(p.id);notice('Đã lưu hành chính và lịch sử thay đổi.','success');});bindPatientAge();}
function newVisit(){if(isAdmin())return;const id=crypto.randomUUID();modal('Mở lượt mới',`<div class="field"><label for="visit-code">Mã lượt nguồn (nếu có)</label><input id="visit-code" name="external_id" maxlength="100"></div><div class="field"><label for="occurred">Thời điểm khám</label><input id="occurred" name="occurred_at" type="datetime-local"><small>Để trống khi chưa rõ; không dùng thời điểm mở màn hình.</small></div><div class="field"><label for="new-visit-type">Loại khám</label><select id="new-visit-type" name="visit_type"><option value="">${missing}</option><option value="new">Khám mới</option><option value="followup">Tái khám</option></select></div><div class="field"><label for="new-reason">Lý do khám</label><input id="new-reason" name="reason" maxlength="5000"></div>`,async(data,d)=>{const v=await api('/api/forms/patients/'+state.patient.id+'/visits',{method:'POST',body:{id,external_id:data.get('external_id')||null,occurred_at:toISO(data.get('occurred_at')),metadata:{visit_type:data.get('visit_type')||null,reason:data.get('reason')||null}}});d.close();await openVisit(v.id);});}
function metadataHistory(m={}){const names={reason:'Lý do khám',hpi:'Bệnh sử/diễn biến',visit_type:'Loại khám',primary_diagnosis_code:'Mã bệnh chính',secondary_diagnosis_codes:'Mã bệnh kèm theo',examining_doctor:'Bác sĩ khám',department:'Khoa/phòng',admitted_at:'Tiếp nhận',ended_at:'Kết thúc',allergy_status:'Dị ứng',allergy_details:'Mô tả dị ứng'};return Object.entries(m).map(([k,v])=>`<tr><td>${esc(names[k]||k)}</td><td>${esc(k==='visit_type'?({new:'Khám mới',followup:'Tái khám'}[v]||missing):k==='allergy_status'?({unknown:'Chưa hỏi/chưa biết',none:'Đã xác nhận không có',known:'Đã ghi nhận'}[v]||missing):k.endsWith('_at')?displayDate(v):fmt(v))}</td><td>Thông tin lượt</td></tr>`).join('');}
async function showHistory(){const rows=await api('/api/forms/visits/'+state.visit.id+'/history');shell(`<div class="toolbar"><h1>Lịch sử chỉnh sửa</h1><button data-action="back-form">← Lượt khám</button></div>${context()}<div class="card history">${rows.length?rows.map(h=>`<details><summary>Lần lưu ${h.revision} · ${esc(h.username||missing)} · ${esc(displayDate(h.created_at))}</summary><div class="table-wrap"><table><thead><tr><th>Trường lúc lưu</th><th>Giá trị</th><th>Nguồn</th></tr></thead><tbody><tr><td>Thời điểm khám</td><td>${esc(displayDate(h.occurred_at))}</td><td>Thông tin lượt</td></tr>${metadataHistory(h.metadata_json||h.metadata)}${Object.entries(h.values_json||{}).map(([k,v])=>`<tr><td>${esc(h.definitions_json?.[k]?.label||k)}</td><td class="result-cell">${valueContent(h.definitions_json?.[k],v)}</td><td>${esc(sourceName(h.sources_json?.[k]?.kind))}${(h.sources_json?.[k]?.source_name||h.sources_json?.[k]?.filename)?'<small>'+esc(h.sources_json[k].source_name||h.sources_json[k].filename)+'</small>':''}${h.sources_json?.[k]?.location?'<small>'+esc(h.sources_json[k].location)+'</small>':''}</td></tr>`).join('')}</tbody></table></div></details>`).join(''):'<div class="empty">Chưa có lần lưu nào.</div>'}</div>`);}
async function patientHistory(){const rows=await api('/api/forms/patients/'+state.patient.id+'/history'),labels={display_name:'Tên hiển thị',date_of_birth:'Ngày sinh',sex:'Giới tính',insurance_number:'Mã BHYT',external_id:'Mã nguồn'};shell(`<div class="toolbar"><h1>Lịch sử hành chính</h1><button data-action="back-visits">← Hồ sơ</button></div><div class="card history">${rows.length?rows.map(h=>`<details><summary>Lần chỉnh ${esc(h.revision)}${h.username?' · '+esc(h.username):''} · ${esc(displayDate(h.created_at))}</summary><div class="table-wrap"><table><thead><tr><th>Thông tin</th><th>Trước</th><th>Sau</th></tr></thead><tbody>${Object.entries(labels).map(([k,l])=>`<tr><td>${l}</td><td>${esc(k==='sex'?({male:'Nam',female:'Nữ',other:'Khác'}[h.before_json?.[k]]||missing):fmt(h.before_json?.[k]))}</td><td>${esc(k==='sex'?({male:'Nam',female:'Nữ',other:'Khác'}[h.after_json?.[k]]||missing):fmt(h.after_json?.[k]))}</td></tr>`).join('')}</tbody></table></div></details>`).join(''):'<p>Chưa có thay đổi hành chính.</p>'}</div>`);}
function showFields(){if(!isAdmin())throw new Error('Chỉ Admin được chỉnh biểu mẫu.');state.page='fields';shell(`<div class="toolbar"><div><h1>Chỉnh biểu mẫu</h1><p class="muted">Lưu cấu trúc tạo phiên bản cho lượt mới. Các lượt đã có giữ mẫu của mình.</p></div><button class="primary" data-action="new-field">Thêm trường</button></div><div class="card"><div class="field"><label for="field-search">Tìm nhãn, mã hoặc nhóm</label><input type="search" id="field-search"></div><div class="table-wrap"><table><thead><tr><th>Nhãn / mã</th><th>Nhóm</th><th>Kiểu / đơn vị</th><th>Phiên bản</th><th>Trạng thái</th><th></th></tr></thead><tbody id="field-rows">${fieldRows(state.fields)}</tbody></table></div></div>`);document.getElementById('field-search').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('field-rows').innerHTML=fieldRows(state.fields.filter(f=>(f.code+' '+f.label+' '+f.group).toLowerCase().includes(q)));};}
function fieldRows(fields){return fields.map(f=>`<tr><td><strong>${esc(f.label)}</strong><small>${esc(f.code)}</small></td><td>${esc(f.group)}</td><td>${esc(types[f.type])}${f.unit?' · '+esc(f.unit):''}</td><td>${f.version}</td><td>${!f.active?'Ngừng dùng':f.type==='unavailable'?'Chưa đặc tả':'Đang dùng'}</td><td><button data-edit-field="${esc(f.code)}" ${f.type==='unavailable'?'disabled':''}>Sửa</button></td></tr>`).join('');}
function fieldDialog(code){if(!isAdmin())return;const old=state.fields.find(f=>f.code===code),groups=[...new Set([...groupsDefault,...state.fields.map(f=>f.group)])];modal(old?'Sửa định nghĩa':'Thêm trường dữ liệu',`<div class="grid"><div class="field"><label for="def-label">Nhãn trường</label><input id="def-label" name="label" value="${esc(old?.label)}" maxlength="200" required></div><div class="field"><label for="def-code">Mã trường ổn định</label><input id="def-code" name="code" value="${esc(old?.code)}" ${old?'readonly':''} pattern="[a-z][a-z0-9_]{1,79}" required></div><div class="field"><label for="def-group">Nhóm</label><select id="def-group" name="group">${groups.map(g=>`<option ${g===(old?.group||'Trường bổ sung')?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div class="field"><label for="def-type">Kiểu dữ liệu</label><select id="def-type" name="type" ${old?'disabled':''}>${Object.entries(types).filter(([k])=>!['medications','results','unavailable'].includes(k)||old?.type===k).map(([k,v])=>`<option value="${k}" ${old?.type===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="def-unit">Đơn vị đã xác định</label><input id="def-unit" name="unit" list="units" value="${esc(old?.unit)}" ${old?'readonly':''} maxlength="60"><datalist id="units">${[...new Set(state.fields.map(f=>f.unit).filter(Boolean))].map(u=>`<option value="${esc(u)}">`).join('')}</datalist><small>Để trống khi không có đơn vị; chưa tự chuyển đơn vị cũ.</small></div><div class="field"><label for="def-order">Thứ tự</label><input id="def-order" name="order" type="number" min="0" max="10000" value="${old?.order??1000}" required></div><div class="field wide"><label for="def-help">Hướng dẫn ngắn</label><textarea id="def-help" name="help" maxlength="1000">${esc(old?.help)}</textarea></div>${!old?'<div class="field wide"><label for="def-choices">Lựa chọn: mỗi dòng mã|nhãn</label><textarea id="def-choices" name="choices" placeholder="ma_1|Nhãn lựa chọn"></textarea></div>':''}${old?`<label class="check wide"><input name="active" type="checkbox" ${old.active?'checked':''}> Đang sử dụng</label>`:''}</div><p class="muted">Trường bổ sung chưa tự tham gia AI.</p><button type="button" id="preview-field">Xem trước</button><div id="field-preview" class="card" hidden></div>`,async(data,d)=>{const body=old?{expected_version:old.version,label:data.get('label'),group:data.get('group'),help:data.get('help'),order:Number(data.get('order')),active:data.has('active')}:definitionFrom(data);await api('/api/forms/fields'+(old?'/'+old.code:''),{method:old?'PATCH':'POST',body});d.close();await loadFields();showFields();notice('Đã lưu phiên bản biểu mẫu mới.','success');},'Lưu phiên bản mới');document.getElementById('preview-field').onclick=()=>{try{const data=new FormData(document.querySelector('dialog form')),definition=old?{...old,label:data.get('label'),group:data.get('group'),help:data.get('help')}:definitionFrom(data),box=document.getElementById('field-preview');box.hidden=false;box.innerHTML='<h3>'+esc(definition.group)+'</h3>'+fieldWidget(definition,null,true);}catch(e){document.querySelector('.dialog-error').textContent=e.message;}};}
function definitionFrom(data){return {code:data.get('code'),label:data.get('label'),group:data.get('group'),type:data.get('type'),unit:data.get('unit')||null,help:data.get('help'),order:Number(data.get('order')),active:true,choices:['select','multiselect'].includes(data.get('type'))?String(data.get('choices')||'').split('\n').filter(s=>s.trim()).map(s=>{const [code,...label]=s.split('|');return {code:code.trim(),label:label.join('|').trim()};}):[]};}
async function navigate(page){if(!confirmLeave())return;captureMapping();if(page==='patients')await loadPatients();else if(page==='fields'){if(!isAdmin())throw new Error('Chỉ Admin được chỉnh biểu mẫu.');await loadFields();showFields();}else{if(isAdmin())throw new Error('Admin chỉ đọc dữ liệu khám.');await loadImportPresets();showImport();}resetDraft();state.page=page;}

const importStatus={fill:'Bổ sung vào ô trống',conflict:'Xung đột — giữ hiện có',unchanged:'Không thay đổi',source_null:'Nguồn trống — không xóa đích',unmapped:'Chưa ánh xạ',error:'Lỗi'};
function importSteps(stage){return '<div class="steps" aria-label="Tiến trình nhập">'+['Nguồn','Cấu trúc','Ánh xạ','Đối chiếu','Kết quả'].map((s,i)=>`<span class="step ${stage===i?'active':''}">${i+1}. ${s}</span>`).join('')+'</div>';}
function showImport(){state.page='excel';state.import=state.import||{stage:0,mapping:{},sheet:'',header_row:1,fileGeneration:0};renderImport();}
function columnOptions(selected){return '<option value="">Chưa chọn cột</option>'+state.import.columns.map(c=>`<option value="${c.column}" ${Number(selected)===c.column?'selected':''}>${esc(c.letter+' · '+(c.header||'Không có nhãn'))}</option>`).join('');}
function renderImport(){const im=state.import;let content='';
if(im.stage===0)content=`<div class="card"><h2>Chọn workbook Excel</h2><p>Đọc file .xlsx từ HIS hoặc mẫu giả lập. Chưa có kết nối trực tiếp hay xác nhận tương thích HIS của viện.</p><p class="muted">Tối đa 4 MiB; sheet 500 cột và 1000 dòng dữ liệu; 100 bản ghi mỗi lần nhập. Không chạy công thức/macro.</p><div class="field"><label for="excel-file">File .xlsx</label><input id="excel-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div>${im.filename?'<p>Đã chọn: '+esc(im.filename)+'</p>':''}<p id="file-read-status" class="muted" role="status">${im.reading?'Đang đọc file…':''}</p><div class="actions" style="margin-top:18px"><button id="excel-inspect" class="primary" data-import="inspect-file" ${!im.content_base64||im.reading?'disabled':''}>Đọc cấu trúc</button><button data-import="template">Tải mẫu Excel giả lập</button></div></div>`;
if(im.stage===1)content=`<div class="card"><h2>Chọn sheet và dòng tiêu đề</h2><p class="muted">${esc(im.filename)} · Không tự chọn sheet/header thay người dùng.</p><div class="grid"><div class="field"><label for="excel-sheet">Sheet</label><select id="excel-sheet"><option value="">Chọn sheet</option>${im.sheets.map(s=>`<option ${s===im.sheet?'selected':''} value="${esc(s)}">${esc(s)}</option>`).join('')}</select></div><div class="field"><label for="excel-header">Dòng tiêu đề (1–100)</label><input id="excel-header" type="number" min="1" max="100" value="${im.header_row}"></div></div><div class="actions" style="margin-top:18px"><button data-import="source">← Chọn lại file</button><button class="primary" data-import="inspect-sheet">Xem cột và mẫu dòng</button></div></div>`;
if(im.stage===2)content=`<div class="card"><h2>Đối chiếu định danh</h2><p>${esc(im.filename)} · Sheet ${esc(im.sheet)} · Tiêu đề hàng ${im.header_row}</p><div id="identity-fields" style="margin-top:15px">${identityFields()}</div><details style="margin-top:18px"><summary>Xem mẫu dòng nguồn</summary><div class="table-wrap"><table><thead><tr><th>Hàng</th>${im.columns.map(c=>'<th>'+esc(c.letter+' · '+(c.header||'Không có nhãn'))+'</th>').join('')}</tr></thead><tbody>${im.sample.map(r=>'<tr><th>'+r.row+'</th>'+r.values.map(v=>'<td>'+esc(fmt(v))+'</td>').join('')+'</tr>').join('')}</tbody></table></div></details></div><div class="card"><h2>Ánh xạ cột vào trường đã tồn tại</h2>${presetContent()}<p class="muted">Cột chưa chọn đích được bỏ qua rõ ràng. Không tự tạo trường hoặc đoán đơn vị/mã giá trị. Danh sách thuốc/kết quả từ Excel chưa có hợp đồng nguồn phù hợp; bổ sung bằng biểu mẫu có cấu trúc.</p>${im.columns.map(c=>mappingRow(c)).join('')}<div class="actions" style="margin-top:20px"><button data-import="structure">← Sheet/header</button><button class="primary" data-import="preview">Xem trước (chưa ghi dữ liệu)</button></div></div>`;
if(im.stage===3)content=previewContent();
if(im.stage===4)content=resultContent(im.result);
shell(`<div class="toolbar"><div><h1>Nhập file</h1><p class="muted">Nguồn trống không xóa dữ liệu đang có. Ghi đè phải chọn theo từng trường.</p></div><button data-import="history">Lịch sử nhập</button></div>${importSteps(im.stage)}${content}`);
if(im.stage===0)document.getElementById('excel-file').onchange=e=>readImportFile(e.target.files[0]);if(im.stage===2){document.getElementById('preset-select').onchange=e=>applyPreset(e.target.value);app.querySelectorAll('[data-map-target]').forEach(el=>el.onchange=()=>{captureMapping();const f=state.fields.find(f=>f.code===el.value),info=document.getElementById('map-info-'+el.dataset.mapTarget);info.textContent=f?f.label+(f.unit?' · Đơn vị '+f.unit:''):'';});}
}
function identityFields(){const im=state.import;return `<div class="grid"><div class="field"><label for="identity-patient">Cột mã hồ sơ / mã nguồn</label><select id="identity-patient">${columnOptions(im.patient_column)}</select></div><div class="field"><label for="identity-visit">Cột mã lượt khám</label><select id="identity-visit">${columnOptions(im.visit_column)}</select></div></div><p class="muted">Mỗi dòng phải có đủ cặp mã đã liên kết. Không ghép theo họ tên hoặc tự gán hồ sơ đang mở.</p>`;}
function mappingRow(c){const m=state.import.mapping[c.column]||{};const fields=state.fields.filter(f=>f.active&&!['unavailable','medications','results','multiselect'].includes(f.type));const f=fields.find(f=>f.code===m.target);return `<div class="mapping-row" data-map-row="${c.column}"><div><strong>${esc(c.letter+' · '+(c.header||'Không có nhãn'))}</strong><small style="display:block">Cột nguồn ${c.column}</small></div><div class="field"><label class="sr-only" for="map-${c.column}">Trường đích cho cột ${esc(c.letter)}</label><select id="map-${c.column}" data-map-target="${c.column}"><option value="">Bỏ qua cột này</option>${fields.map(f=>`<option value="${esc(f.code)}" ${m.target===f.code?'selected':''}>${esc(f.label+' · '+types[f.type]+(f.unit?' ('+f.unit+')':''))}</option>`).join('')}</select><small id="map-info-${c.column}">${f?'Mã '+esc(f.code)+(f.unit?' · Đơn vị đích '+esc(f.unit):''):''}</small><label class="check"><input type="checkbox" id="unit-${c.column}" ${m.unit_confirmed?'checked':''}> Đơn vị nguồn trùng đích (khi trường có đơn vị)</label></div><div class="field"><label for="convert-${c.column}">Cách đọc đã xác định</label><select id="convert-${c.column}">${[['native','Giữ kiểu ô gốc'],['dot_number','Chuỗi số dấu chấm'],['boolean_01','Bảng mã 0 = Không, 1 = Có'],['boolean_true_false','Bảng mã true/false'],['iso_date','Ngày ISO / ô ngày Excel']].map(([value,label])=>`<option value="${value}" ${(m.conversion||'native')===value?'selected':''}>${label}</option>`).join('')}</select></div></div>`;}
function captureMapping(){const im=state.import;if(!im||im.stage!==2)return;for(const c of im.columns||[]){const target=document.getElementById('map-'+c.column);if(target)im.mapping[c.column]={target:target.value,unit_confirmed:Boolean(document.getElementById('unit-'+c.column)?.checked),conversion:document.getElementById('convert-'+c.column)?.value||'native'};}const patient=document.getElementById('identity-patient'),visit=document.getElementById('identity-visit');if(patient)im.patient_column=Number(patient.value)||null;if(visit)im.visit_column=Number(visit.value)||null;}
function previewContent(){const plan=state.import.preview;return `<div class="status success">Xem trước chỉ đọc: chưa ghi hồ sơ, lượt, lịch sử hoặc lần nhập. Có ${plan.eligible} dòng đủ điều kiện và ${plan.errors} dòng còn lỗi.</div>${plan.records.map(r=>`<div class="card"><div class="toolbar"><div class="import-target"><h2>Bản ghi ${r.index+1} · Đích: ${esc(r.target_patient_code||'Chưa xác định hồ sơ')}</h2><p><strong>${esc(r.target_patient_name||'Chưa xác định tên người bệnh')}</strong> · ${esc(r.visit_external_id||(r.visit_id?'Lượt được đối chiếu, chưa có mã nguồn':'Chưa xác định lượt'))}</p><p class="visit-time">Thời điểm khám đích: ${esc(displayDate(r.target_occurred_at))}</p><small>Mã trong file: ${esc(r.patient_code||'Thiếu mã hồ sơ')} / ${esc(r.visit_external_id||'Thiếu mã lượt')}</small></div><label class="check"><input type="checkbox" data-import-record="${r.index}" ${r.status==='eligible'?'checked':'disabled'}> Chọn nhập dòng này</label></div>${r.errors.length?'<div class="status error">'+r.errors.map(e=>'<p>'+esc(e.path)+' · '+esc(e.reason)+(Object.hasOwn(e,'raw')?' · Nguồn: '+esc(fmt(e.raw)):'')+'</p>').join('')+'</div>':''}<div class="table-wrap"><table><thead><tr><th>Vị trí / Trường</th><th>Giá trị gốc</th><th>Dữ liệu đích</th><th>Nguồn nhập sau kiểm tra</th><th>Quyết định</th></tr></thead><tbody>${r.fields.map(f=>`<tr><td>${esc(f.label||f.code||f.source)}<small style="display:block">${esc(f.path)}</small></td><td class="result-cell">${esc(fmt(f.raw))}</td><td class="result-cell">${esc(fmt(f.current))}${f.current_source?'<small style="display:block">Nguồn: '+esc(f.current_source.kind)+'</small>':''}</td><td class="result-cell">${esc(fmt(f.incoming))}</td><td>${f.status==='conflict'?`<select data-override="${r.index}" data-code="${esc(f.code)}" aria-label="Xử lý xung đột ${esc(f.label)}"><option value="keep">Giữ hiện có</option><option value="override">Thay bằng nguồn nhập</option></select>`:esc(importStatus[f.status]||f.status)}${f.reason?'<p class="field-error">'+esc(f.reason)+'</p>':''}</td></tr>`).join('')}</tbody></table></div></div>`).join('')}<div class="savebar"><div><strong>Kiểm tra hồ sơ/lượt và từng xung đột trước khi xác nhận.</strong><small>Chỉ các dòng đã chọn, hợp lệ được ghi trong một giao dịch.</small></div><div class="actions"><button data-import="mapping">← Sửa ánh xạ</button><button data-import="cancel">Hủy xem trước</button><button class="primary" data-import="commit" ${plan.eligible?'':'disabled'}>Xác nhận nhập các dòng đã chọn</button></div></div>`;}
function resultContent(result){return `<div class="card"><h2>${result.replayed?'Đã nhận diện lần nhập lặp':'Máy chủ đã xác nhận kết quả nhập'}</h2><div class="status success">${result.replayed?'Không ghi thêm dữ liệu. Kết quả lần nhập trước: ' : ''}Đã ghi ${result.written_fields} trường trong ${result.written_records} lượt; bỏ qua ${result.skipped_fields} trường; ${result.unselected_records} dòng không được chọn ghi.</div><p class="muted">Nguồn: ${esc(result.source_name)} · Ánh xạ phiên bản ${esc(result.mapping_version)}</p><div class="table-wrap"><table><thead><tr><th>Hồ sơ / lượt đích</th><th>Số trường ghi</th><th>Phiên bản</th><th>Bỏ qua và lý do</th><th></th></tr></thead><tbody>${result.records.map(r=>`<tr><td><strong>${esc(r.target_patient_code||r.patient_code)}</strong>${r.target_patient_name?'<br>'+esc(r.target_patient_name):''}<br>${esc(r.visit_external_id||'Lượt đã đối chiếu')}<small>Thời điểm khám: ${esc(displayDate(r.target_occurred_at))}</small>${r.target_patient_code?'<small>Mã trong file: '+esc(r.patient_code)+'</small>':''}</td><td>${r.written_fields}</td><td>${r.revision}</td><td>${r.skipped.map(s=>esc(s.field)+': '+esc(importStatus[s.reason]||s.reason)).join('<br>')||'Không có'}</td><td><button data-visit="${r.visit_id}">Mở biểu mẫu / bổ sung tay</button></td></tr>`).join('')}</tbody></table></div><details style="margin-top:18px"><summary>Chi tiết dòng không được ghi</summary>${unselectedContent(result.unselected||[])}</details><div class="actions" style="margin-top:18px"><button data-import="new">Nhập file khác</button><button data-import="history">Lịch sử nhập</button></div></div>`;}
async function downloadTemplate(){const response=await fetch('/api/forms/imports/template.xlsx',{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw new Error('Không tải được mẫu Excel');const url=URL.createObjectURL(await response.blob());const anchor=document.createElement('a');anchor.href=url;anchor.download='synthetic-form-template.xlsx';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function showImportHistory(){const rows=await api('/api/forms/imports/history');shell(`<div class="toolbar"><h1>Lịch sử nhập file của tài khoản</h1><button data-import="resume">← Nhập file</button></div><div class="card history">${rows.length?rows.map(r=>`<details><summary>${esc(new Date(r.created_at).toLocaleString('vi-VN'))} · ${esc(r.result.source_name)} · ${r.result.written_fields} trường đã ghi</summary>${resultContent(r.result)}<details><summary>Ánh xạ đã dùng</summary>${mappingSummary(r.mapping)}</details></details>`).join(''):'<div class="empty">Chưa có lần nhập đã xác nhận.</div>'}</div>`);}
async function importAction(action){const im=state.import;if(action==='save-preset')return savePreset();if(action==='template')return downloadTemplate();if(action==='history'){captureMapping();return showImportHistory();}if(action==='resume')return renderImport();if(action==='new'||action==='cancel'){state.import={stage:0,mapping:{},sheet:'',header_row:1,fileGeneration:0};renderImport();return;}if(action==='source'){im.stage=0;renderImport();return;}if(action==='structure'){captureMapping();im.stage=1;renderImport();return;}if(action==='mapping'){im.stage=2;renderImport();return;}
if(action==='inspect-file'){if(im.reading)throw new Error('File đang được đọc, vui lòng chờ.');if(!im.content_base64)throw new Error('Chọn file .xlsx hợp lệ trước.');const info=await api('/api/forms/imports/excel/inspect',{method:'POST',body:{filename:im.filename,content_base64:im.content_base64}});im.sheets=info.sheets;im.stage=1;renderImport();return;}
if(action==='inspect-sheet'){im.sheet=document.getElementById('excel-sheet').value;im.header_row=Number(document.getElementById('excel-header').value);if(!im.sheet)throw new Error('Chọn sheet rõ ràng trước.');const info=await api('/api/forms/imports/excel/inspect',{method:'POST',body:{filename:im.filename,content_base64:im.content_base64,sheet:im.sheet,header_row:im.header_row}});if(!info.columns.length)throw new Error('Sheet hoặc dòng tiêu đề không có cột.');im.columns=info.columns;im.sample=info.sample;if(im.structureKey!==im.sheet+'|'+im.header_row){im.mapping={};im.patient_column=null;im.visit_column=null;}im.structureKey=im.sheet+'|'+im.header_row;im.stage=2;renderImport();return;}
if(action==='preview'){captureMapping();const mapping=Object.entries(im.mapping).filter(([,m])=>m.target).map(([column,m])=>({column:Number(column),...m}));if(!mapping.length)throw new Error('Chọn ít nhất một cột để ánh xạ; các cột khác được bỏ qua.');const body={filename:im.filename,content_base64:im.content_base64,sheet:im.sheet,header_row:im.header_row,mapping};if(!im.patient_column||!im.visit_column)throw new Error('Chọn cột mã hồ sơ và mã lượt.');body.patient_column=im.patient_column;body.visit_column=im.visit_column;im.preview=await api('/api/forms/imports/excel/preview',{method:'POST',body});im.commitBody=null;im.stage=3;renderImport();return;}
if(action==='commit'){const records=[...document.querySelectorAll('[data-import-record]:checked')].map(el=>({index:Number(el.dataset.importRecord),override_fields:[...document.querySelectorAll(`[data-override="${el.dataset.importRecord}"]`)].filter(s=>s.value==='override').map(s=>s.dataset.code)}));if(!records.length)throw new Error('Chọn ít nhất một dòng hợp lệ để nhập.');im.commitBody={preview_token:im.preview.preview_token,records};im.result=await api('/api/forms/imports/commit',{method:'POST',body:im.commitBody});im.stage=4;renderImport();}}
function updateFileReadUI(im){if(state.import!==im||state.page!=='excel')return;const inspect=document.getElementById('excel-inspect'),status=document.getElementById('file-read-status');if(inspect){const disabled=im.reading||!im.content_base64;if(busyControls?.has(inspect))busyControls.set(inspect,disabled);inspect.disabled=state.busy||disabled;}if(status)status.textContent=im.reading?'Đang đọc file…':im.filename?'File đã sẵn sàng: '+im.filename:'';}
async function readImportFile(file){const im=state.import,generation=(im.fileGeneration||0)+1;Object.assign(im,{fileGeneration:generation,reading:false,content_base64:null,filename:null,preview:null,result:null,commitBody:null,columns:[],sheets:[],mapping:{},sheet:'',structureKey:null,patient_column:null,visit_column:null});updateFileReadUI(im);if(!file)return;if(file.size>4194304){notice('File vượt giới hạn 4 MiB.');return;}if(!file.name.toLowerCase().endsWith('.xlsx')){notice('Chỉ nhận file .xlsx.');return;}im.reading=true;updateFileReadUI(im);try{const buffer=new Uint8Array(await file.arrayBuffer());if(state.import!==im||im.fileGeneration!==generation)return;let binary='';for(let start=0;start<buffer.length;start+=32768)binary+=String.fromCharCode(...buffer.subarray(start,start+32768));Object.assign(im,{filename:file.name,content_base64:btoa(binary)});if(state.page==='excel')notice('Đã đọc file. Chọn “Đọc cấu trúc” để tiếp tục.','success');}catch(e){if(state.import===im&&im.fileGeneration===generation&&state.page==='excel')notice('Không đọc được file. Vui lòng chọn lại.');}finally{if(im.fileGeneration===generation){im.reading=false;updateFileReadUI(im);}}}

async function loadImportPresets(){state.presets=await api('/api/forms/imports/presets');}
function presetContent(){return `<div class="preset-box"><div class="field"><label for="preset-select">Cấu hình theo nguồn đã lưu</label><select id="preset-select"><option value="">Chọn cấu hình</option>${state.presets.map(p=>`<option value="${esc(p.id)}">${esc(p.name+' · '+p.source_name)}</option>`).join('')}</select></div><button type="button" data-import="save-preset">Lưu cấu hình theo nguồn</button></div>`;}
function applyPreset(id){captureMapping();const p=state.presets.find(p=>p.id===id);if(!p)return;const im=state.import,m=p.mapping;if(m.sheet!==im.sheet||Number(m.header_row)!==Number(im.header_row)){notice('Cấu hình thuộc sheet/dòng tiêu đề khác. Chọn đúng cấu trúc nguồn trước.');return;}const columns=new Set(im.columns.map(c=>c.column));if((m.columns||[]).some(c=>!columns.has(c.column))||!columns.has(m.patient_column)||!columns.has(m.visit_column)){notice('Cấu hình không khớp các cột trong file này.');return;}im.mapping=Object.fromEntries((m.columns||[]).map(({column,...rest})=>[column,rest]));im.patient_column=m.patient_column;im.visit_column=m.visit_column;im.preview=null;renderImport();notice('Đã áp dụng cấu hình. Kiểm tra cột và đơn vị trước khi xem trước.','success');}
function savePreset(){captureMapping();const im=state.import,columns=Object.entries(im.mapping).filter(([,m])=>m.target).map(([column,m])=>({column:Number(column),...m}));if(!columns.length||!im.patient_column||!im.visit_column)throw new Error('Chọn cặp cột định danh và ít nhất một trường trước khi lưu cấu hình.');const id=crypto.randomUUID();modal('Lưu cấu hình ánh xạ',`<div class="field"><label for="preset-name">Tên cấu hình / phiên bản</label><input id="preset-name" name="name" maxlength="120" required></div><div class="field"><label for="preset-source">Nguồn file</label><input id="preset-source" name="source_name" maxlength="200" required></div><p class="muted">Cấu hình lưu theo tài khoản. Cần kiểm tra lại khi cấu trúc nguồn thay đổi.</p>`,async(data,d)=>{await api('/api/forms/imports/presets',{method:'POST',body:{id,name:data.get('name'),source_name:data.get('source_name'),mapping:{sheet:im.sheet,header_row:im.header_row,patient_column:im.patient_column,visit_column:im.visit_column,columns}}});await loadImportPresets();d.close();renderImport();notice('Đã lưu cấu hình theo nguồn.','success');});}
async function handleClick(e){const b=e.target.closest('button');if(!b||b.disabled||state.busy)return;if(b.dataset.action==='toggle-password'){const password=document.getElementById('password'),show=password.type==='password';password.type=show?'text':'password';b.textContent=show?'Ẩn':'Hiện';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',show?'Ẩn mật khẩu':'Hiện mật khẩu');return;}try{await runAction(async()=>{if(b.dataset.import){if(isAdmin())throw new Error('Admin chỉ đọc dữ liệu khám.');return importAction(b.dataset.import);}if(b.dataset.page)return navigate(b.dataset.page);if(b.dataset.patient){if(confirmLeave())return openPatient(b.dataset.patient);return;}if(b.dataset.visit){if(confirmLeave())return openVisit(b.dataset.visit);return;}if(b.dataset.group){state.group=b.dataset.group;showForm();document.querySelector('.clinical h2')?.focus();return;}if(b.dataset.editField)return fieldDialog(b.dataset.editField);for(const action of ['addItem','removeItem','emptyList','nullList'])if(Object.hasOwn(b.dataset,action)){if(isAdmin())return;const code=b.dataset[action],rows=structuredClone(currentValue(code))||[];if(action==='addItem')rows.push({name:null});if(action==='removeItem')rows.splice(Number(b.dataset.index),1);if(action==='emptyList')rows.length=0;if(action==='emptyList'||action==='nullList'){for(const key of Object.keys(state.invalid))if(key===code||key.startsWith(code+':'))delete state.invalid[key];}else if(action==='removeItem'){const removed=Number(b.dataset.index),next={};for(const [key,value]of Object.entries(state.invalid)){if(key.startsWith(code+':')){const parts=key.split(':'),index=Number(parts[1]);if(index===removed)continue;if(index>removed)parts[1]=String(index-1);next[parts.join(':')]=value;}else next[key]=value;}state.invalid=next;}dirty(code,action==='nullList'?null:rows);showForm();return;}switch(b.dataset.action){case'logout':if(confirmLeave()){await api('/api/v1/auth/logout',{method:'POST'});sessionStorage.removeItem('forms_token');location.href='/login';}break;case'new-patient':newPatient();break;case'edit-patient':if(confirmLeave())editPatient();break;case'patient-history':if(confirmLeave())await patientHistory();break;case'new-visit':newVisit();break;case'back-visits':if(confirmLeave())await openPatient(state.patient.id);break;case'save':await save();break;case'reload-visit':if(confirmLeave('Tải dữ liệu mới nhất và bỏ thay đổi chưa lưu?'))await openVisit(state.visit.id);break;case'history':await showHistory();break;case'back-form':showForm();break;case'new-field':fieldDialog();break;case'clear-search':document.getElementById('patient-search').value='';document.getElementById('patient-list').innerHTML=patientItems(state.patients);break;}});}catch(err){notice(err.message);}}
function handleInput(e){const el=e.target;if(isAdmin())return;if(el.dataset.field){const f=visitFields().find(f=>f.code===el.dataset.field);if(!f)return;try{let v=el.value;if(['date','datetime'].includes(f.type)&&el.validity?.badInput)throw new Error('Ngày giờ không hợp lệ.');if(['number','integer'].includes(f.type))v=numericValue(el,f);else if(f.type==='multiselect')v=[...el.selectedOptions].map(o=>o.value);else if(v==='')v=null;else if(f.type==='datetime')v=toISO(v);else if(f.type==='boolean')v=v==='true';setInvalid(f.code,'');dirty(f.code,v);}catch(err){setInvalid(f.code,err.message);}}if(el.dataset.repeat){const code=el.dataset.repeat,rows=structuredClone(currentValue(code))||[],index=Number(el.dataset.index);if(!rows[index])return;try{const column=el.dataset.column;if(el.validity?.badInput)throw new Error(column==='observed_at'||column.endsWith('_date')?'Ngày giờ không hợp lệ.':'Cần nhập giá trị hợp lệ.');rows[index][column]=['value','dose_value'].includes(column)?numericValue(el,{type:'number',constraints:column==='dose_value'?{minimum:0}:{}}):column==='observed_at'?toISO(el.value):el.value||null;setInvalid(code,'');setInvalid(code+':'+index+':'+el.dataset.column,'');dirty(code,rows);if(el.dataset.column==='test_code'){const f=visitFields().find(f=>f.code===code),unit=document.getElementById(`f-${code}-${index}-unit`);if(f&&unit){const choices=repeatChoices(f,'unit',rows[index]);if(unit.tagName==='SELECT'&&choices)unit.innerHTML=repeatOptionsHTML(choices,rows[index].unit);else if((unit.tagName==='SELECT')!==Boolean(choices))showForm();}}}catch(err){setInvalid(code+':'+index+':'+el.dataset.column,err.message);}}if(el.dataset.metadata){const code=el.dataset.metadata;let v=el.value||null;try{if(code==='secondary_diagnosis_codes')v=v?v.split(/[,;\n]+/).map(s=>s.trim()).filter(Boolean):null;else if(code.endsWith('_at')){if(el.validity?.badInput)throw new Error('Ngày giờ không hợp lệ.');v=toISO(v);}if(JSON.stringify(v)===JSON.stringify(state.visit.metadata?.[code]??null))delete state.metadataDirty[code];else state.metadataDirty[code]=v;setInvalid('meta-'+code,'');state.pending=null;refreshDraftStatus();}catch(err){setInvalid('meta-'+code,err.message);}}if(el.dataset.visitField){try{if(el.validity?.badInput)throw new Error('Ngày giờ không hợp lệ.');const value=toISO(el.value);if(value===(state.visit.occurred_at||null))delete state.visitDirty.occurred_at;else state.visitDirty.occurred_at=value;setInvalid('occurred_at','');const header=document.getElementById('context-occurred');if(header)header.textContent='Thời điểm khám: '+displayDate(value);const contextAge=document.getElementById('context-age');if(contextAge){const n=value?ageOn(state.visit.demographics_snapshot?.date_of_birth,value):null;contextAge.textContent=n===null?'':' · '+n+' tuổi tại lần khám';}const age=document.getElementById('derived-tuoi');if(age){const computed=value?ageOn(state.visit.demographics_snapshot?.date_of_birth,value):null;age.textContent=computed===null?missing:computed+' tuổi';}state.pending=null;refreshDraftStatus();}catch(err){setInvalid('occurred_at',err.message);}}}
app.addEventListener('click',handleClick);
app.addEventListener('input',handleInput);
app.addEventListener('change',e=>{const el=e.target;if(Object.hasOwn(el.dataset,'groupSelect')){state.group=el.value;showForm();document.querySelector('.clinical h2')?.focus();return;}if(el.dataset.multiKnown&&!isAdmin()){const code=el.dataset.multiKnown;dirty(code,el.checked?[]:null);const select=document.getElementById('f-'+code);select.disabled=!el.checked;[...select.options].forEach(o=>o.selected=false);}});
window.addEventListener('beforeunload',e=>{if(hasDraft()){e.preventDefault();e.returnValue='';}});
function unselectedContent(rows){return rows.length?`<div class="row-list">${rows.map(r=>`<div class="list-item"><div><strong>Dòng ${Number(r.index)+1}</strong><p>${r.status==='eligible'?'Hợp lệ, không được chọn':'Chưa đủ điều kiện'}</p>${(r.errors||[]).map(e=>`<p class="field-error">${esc(e.path)} · ${esc(e.reason)}</p>`).join('')}</div></div>`).join('')}</div>`:'<p>Không có dòng bị bỏ lại.</p>';}
function mappingSummary(mapping={}){const conversions={native:'Giữ kiểu ô gốc',dot_number:'Số dấu chấm',boolean_01:'0 = Không, 1 = Có',boolean_true_false:'true/false',iso_date:'Ngày Excel / ISO'};return `<p>Sheet ${esc(mapping.sheet||missing)} · Tiêu đề hàng ${esc(mapping.header_row??missing)} · Cột mã hồ sơ ${esc(mapping.patient_column??missing)} · Cột mã lượt ${esc(mapping.visit_column??missing)}</p><div class="table-wrap"><table><thead><tr><th>Cột nguồn</th><th>Trường đích</th><th>Cách đọc</th><th>Đơn vị</th></tr></thead><tbody>${(mapping.columns||[]).map(c=>{const f=state.fields.find(f=>f.code===c.target);return `<tr><td>${esc(c.column)}</td><td>${esc(f?.label||c.target)}</td><td>${esc(conversions[c.conversion]||c.conversion)}</td><td>${esc(f?.unit||'Không có đơn vị')}${c.unit_confirmed?' · Đã đối chiếu':''}</td></tr>`;}).join('')}</tbody></table></div>`;}

initialize();
})();
